// Third-party notices (Build 26.78). THIRD_PARTY_NOTICES.txt is generated by `npm run notices`, installed next to
// the app and shown in Settings. The full text (~140 kB) is a separate chunk loaded on first open; only the counts
// are in the main bundle.
import type { LegalSection } from "./document";
import summary from "./third-party-summary.json";

export interface ThirdPartySummary {
  appVersion: string;
  rust: number;
  npm: number;
  fonts: number;
  total: number;
  licenseTexts: number;
}

export const THIRD_PARTY_SUMMARY: ThirdPartySummary = summary;

/** One `====` part of the notices file (About, Rust crates, npm packages, Fonts, Licence texts). */
export interface NoticesPart {
  title: string;
  sections: LegalSection[];
}

const underline = (line: string | undefined, heading: string, char: string) =>
  line !== undefined && heading.length > 0 && line.length === heading.length && line === char.repeat(heading.length);

// Licence texts use the same underline style themselves (MPL-2.0 does), so only these exact headings count.
const PART_TITLE = /^(FundedFlow third-party notices|(Rust crates|npm packages|Fonts|Licence texts) \(\d+\))$/;
const LICENCE_TEXT_HEADING = /^\[T\d+\] \S/;

/**
 * Splits the notices text into parts and sections by its underlined headings (`====` parts, `----` sections). Each
 * section's paragraphs are separated by blank lines and keep their own line breaks. Text stays text.
 */
export function parseNotices(text: string): NoticesPart[] {
  const lines = text.replace(/\r\n?/g, "\n").split("\n");
  const parts: NoticesPart[] = [];
  let section: LegalSection | null = null;
  let paragraph: string[] = [];
  const flush = () => {
    if (section && paragraph.length) section.paragraphs.push(paragraph.join("\n"));
    paragraph = [];
  };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const part = parts[parts.length - 1];
    if (PART_TITLE.test(line) && underline(lines[i + 1], line, "=")) {
      flush();
      parts.push({ title: line, sections: [] });
      section = null;
      i++;
    } else if (part && underline(lines[i + 1], line, "-") && (!part.title.startsWith("Licence texts") || LICENCE_TEXT_HEADING.test(line))) {
      flush();
      section = { heading: line, paragraphs: [] };
      part.sections.push(section);
      i++;
    } else if (line === "") {
      flush();
    } else {
      paragraph.push(line);
    }
  }
  flush();
  return parts.filter(part => part.sections.length);
}

/** Loads and parses the full notices: a dynamic import, so Vite keeps the text out of the main bundle. */
export async function loadThirdPartyNotices(): Promise<NoticesPart[]> {
  const { default: text } = await import("../../THIRD_PARTY_NOTICES.txt?raw");
  return parseNotices(text);
}
